async function api(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: { "content-type": "application/json", ...options.headers },
  });
  const body = await response.json();
  if (!response.ok)
    throw Object.assign(
      Error(body.error?.message || "Could not complete the request."),
      { status: response.status, code: body.error?.code },
    );
  return body.data;
}
const post = (url, data, method = "POST") =>
  api(url, { method, body: JSON.stringify(data) });
const go = (path) => {
  if (location.hash.slice(1) === path) {
    route = path;
    render();
  } else location.hash = path;
};
function toast(text, error = false) {
  const box = $("#toast");
  box.textContent = text;
  box.className = "toast visible" + (error ? " error" : "");
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => box.classList.remove("visible"), 6500);
}
const errorBox = (message) =>
  `<div class="alert error" role="alert">${esc(message)}</div>`;
function bind(selector, fn, event = "click") {
  const e = $(selector);
  if (e)
    e.addEventListener(event, async (ev) => {
      try {
        await fn(ev);
      } catch (error) {
        toast(error.message, true);
      }
    });
}
