async function render() {
  route = location.hash.slice(1) || "/";
  if (route.startsWith("/reset")) return recovery(true);
  if (route === "/recover") return recovery(false);
  try {
    if (!me) {
      try {
        refs = await api("/api/me");
        me = refs.user;
        offline = false;
      } catch (e) {
        if (e instanceof TypeError || !navigator.onLine) {
          refs = await prepared();
          if (refs) {
            me = refs.user;
            offline = true;
          }
        }
        if (!me) return login();
      }
    }
    if (route === "/")
      route = me.role === "FOCAL_PERSON" ? "/field" : "/monitoring";
    if (route === "/field") await field();
    else if (route === "/field/reports/new") await reportForm();
    else if (route === "/field/drafts") await drafts();
    else if (route === "/field/reports") await reports(true);
    else if (route.startsWith("/field/reports/"))
      await reportPage(route.split("/").pop());
    else if (route === "/monitoring" && me.role !== "FOCAL_PERSON")
      await monitoring();
    else if (route === "/monitoring/reports" && me.role !== "FOCAL_PERSON")
      await reports();
    else if (route.startsWith("/monitoring/reports/"))
      await reportPage(route.split("/").pop());
    else if (["/monitoring/items", "/monitoring/map"].includes(route))
      await items();
    else if (route.startsWith("/monitoring/items/"))
      await itemPage(route.split("/").pop());
    else if (route === "/admin/users" && me.role === "ADMIN") await users();
    else if (route === "/admin/audit" && me.role === "ADMIN") await audit();
    else if (route === "/admin/reference-data" && me.role === "ADMIN")
      await referenceData();
    else if (route === "/notifications") await notifications();
    else if (route === "/help") help();
    else
      shell(
        empty(
          "This page isn’t available",
          "Choose a page from your workspace navigation.",
        ),
      );
    if (!offline) retryQueued();
  } catch (e) {
    if (e.status === 401) {
      me = null;
      refs = null;
      login();
      $("#loginError").innerHTML = errorBox(e.message);
    } else if (me) {
      shell(
        `${heading("WORKSPACE", "We couldn’t load this view.")}${errorBox(e.message)}<button class="btn" id="retryView">Try again</button><a class="btn" href="#/field/drafts">Open saved drafts</a>`,
      );
      bind("#retryView", render);
    } else login();
  }
}
window.addEventListener("hashchange", () => {
  render();
  window.scrollTo(0, 0);
});
window.addEventListener("offline", () => {
  offline = true;
  const c = $(".connection");
  if (c) {
    c.textContent = "Offline · local drafts";
    c.classList.add("is-offline");
  }
});
window.addEventListener("online", async () => {
  try {
    const r = await api("/api/me");
    if (me && r.user.id === me.id) {
      offline = false;
      refs = r;
      await retryQueued();
      if (route === "/field/drafts" || route === "/field") render();
    }
  } catch {}
});
if ("serviceWorker" in navigator)
  navigator.serviceWorker.register("/sw.js").catch(() => {});
render();
// Refresh read-only overview pages on focus; never replace an in-progress form.
window.addEventListener("focus", () => {
  if (
    me &&
    !offline &&
    [
      "/monitoring",
      "/monitoring/reports",
      "/field",
      "/field/reports",
      "/notifications",
    ].includes(route) &&
    !["INPUT", "SELECT", "TEXTAREA"].includes(document.activeElement?.tagName)
  )
    render();
});
